"""Вердикт по отчёту сквозных проб консоли: исполнено ВСЁ объявленное, упавших нет.

ПРЕДМЕТ. Код возврата прогона отвечает на вопрос «упало ли то, что запускалось».
Он молчит о другом: запускалось ли всё. Проба, выпавшая из набора — переименован
файл, сломался отбор, отвалился каталог с описаниями, — уносит с собой своё
утверждение, а прогон остаётся зелёным. «Ноль упавших» из двух проб и из семи
выглядит одинаково, и различить их можно только сверкой с деревом.

Поэтому здесь три независимых утверждения:

  1. ЧИСЛО. Проб в отчёте столько же, сколько объявлено в дереве. Объявленное
     считается по исходникам проб (`test(` на своей строке), а не выписывается —
     выписанное число разошлось бы с деревом молча, и разошлось бы именно тогда,
     когда пробу добавили и забыли включить.
  2. ИСХОД. Ни одной пробы вне состояния «прошла». Пропуск («skipped») здесь
     ТОЖЕ провал: пропущенная проба — это отсутствующая проверка, и правило
     запрещает её ровно так же, как маску.
  3. АРТЕФАКТ. У каждой УПАВШЕЙ пробы есть вложение трассы (#1287). Трасса —
     единственная запись того, что происходило в браузере; теряется она ровно
     на падении, то есть там, где она и нужна, и теряется ТИХО: код возврата
     прогона о вложениях не знает. Одна такая потеря уже случалась (#1242) и
     была найдена вручную — только потому, что кто-то попытался открыть файл.

И одно различение сверх них (#2780, приёмка F8 §4): УСЛОВИЕ ПРОГОНА. Пробы, чья
посадка создаётся чужим предметом, зависят от проекта условий; упало условие —
исход называется «не выполнилось» с числом сценариев без вердикта, а не красным.
Узнаётся условие по имени проекта в отчёте, а не по тексту отказа.

Отсутствие отчёта — ПРОВАЛ, а не «нечего проверять»: суита, не оставившая
отчёта, не выполнилась, и эта третья категория из вердикта не вычитается.

Печатается объём осмотренного: сколько исходников прочитано, сколько объявлений
в них найдено, сколько записей разобрано в отчёте, сколько проб упало и у
скольких из них трасса есть, а у скольких нет. «Ноль находок» обязано быть
отличимо от «ноль прочитанного», а «упавших без трассы ноль» — от «упавших не
было вовсе»: первое свойство прогона, второе отсутствие предмета, и различает
их только ПАРА чисел.

Запуск:
    python3 .github/scripts/assert-console-probes-verdict.py            # вердикт
    python3 .github/scripts/assert-console-probes-verdict.py --self-test # инъекция
"""

from __future__ import annotations

import json
import re
import sys
import tempfile
from pathlib import Path
from typing import NamedTuple

# Объявление пробы: вызов `test(` в начале логической строки. Форма `test.describe(`
# и `test.skip(` под неё намеренно не подпадают: первая — группа, а не проба;
# вторая обязана ловиться отдельным запретом на пропуски, а не считаться пробой.
DECL = re.compile(r"^[ \t]*test\(", re.MULTILINE)

# Управляющие последовательности цвета из вывода playwright. В журнале шага они
# читаются как мусор и разрывают строку диагноза, поэтому снимаются перед
# печатью — но НЕ перед сверкой: сверка идёт по подстрокам, которых цвет не
# касается.
ANSI = re.compile(r"\x1b\[[0-9;]*m")


def plain(text: str) -> str:
    return ANSI.sub("", text)


# КОДЫ ВОЗВРАТА. Третья категория обязана иметь СВОЙ, иначе она неотличима от
# красноты продукта для всякого, кто читает исход, а не журнал (#1041).
#
#   0 — зелено
#   1 — КРАСНОЕ: вердикт вынесен и он о продукте
#   3 — НЕ ВЫПОЛНИЛОСЬ: вердикта нет ни у одной пробы
#
# Ненулевым остаётся и 3: вычета нет, прогон зелёным не становится. Различается
# не СТРОГОСТЬ, а ТО, ЧТО РАЗБИРАТЬ.
#
# ГРАНИЦА ПРОВЕДЕНА УЗКО, И ЭТО НЕ ОСТОРОЖНИЧАНЬЕ. Код 3 выдаётся ровно там, где
# есть ПОЛОЖИТЕЛЬНОЕ и конкретное свидетельство, что до продукта не дошла ни одна
# проба. Ранняя остановка набора под него НЕ подпадает, хотя тоже зовётся третьей
# категорией в своей строке: останавливает прогон предел падений, а падения эти
# бывают настоящими, продуктовыми. Объявив такой исход «условие не создано», мы
# спрятали бы дефект продукта за словами о недостижимости стенда — то есть
# сделали бы послабление маской, ровно то, что запрещено.
RC_GREEN = 0
RC_RED = 1
RC_UNMET = 3

SPECS_GLOB = "*.spec.ts"

# УСЛОВИЕ ПРОГОНА — СВОЙ ПРОЕКТ ПРОГОНЩИКА (#2780, приёмка F8 §4).
#
# Часть набора исполнима лишь на посадке, которую создаёт чужой предмет: адреса
# церемоний обязана отдавать оболочка консоли, а не чужой экран. Проверка этого
# условия — не проба о продукте, поэтому она живёт в СВОЁМ каталоге
# (`ui-future/e2e/preconditions/`, объявления `*.precondition.ts`) и исполняется
# СВОИМ проектом, от которого проекты зависящих проб объявляют зависимость
# (`playwright.config.ts`). Упало условие — зависящие не стартуют вовсе.
#
# Различение здесь СТРУКТУРНОЕ, а не по тексту отказа: запись условия узнаётся по
# имени проекта, которое кладёт отчёт (`projectName`), а не по словам в её
# сообщении. Распознаватель текста «похожих» отказов стал бы маской ровно так,
# как описано у кодов возврата выше; имя проекта ни одна проба о продукте
# произвести не может.
PRECONDITION_PROJECT = "precondition"
PRECONDITIONS_GLOB = "*.precondition.ts"

# ВЛОЖЕНИЕ ТРАССЫ (#1287). Имя задаёт разбор фикстуры `page` в specs/fixtures.ts:
# он кладёт архив в `testInfo.attachments` под этим именем, а прогонщик переносит
# запись в отчёт как есть. Сверка идёт по ИМЕНИ вложения в отчёте, а не по файлу
# на диске: гейт читает отчёт и о диске ранера не знает — да и предмет #1242 был
# ровно в том, что запись до отчёта НЕ ДОЕХАЛА.
TRACE_ATTACHMENT = "trace"

# Исходы, на которых трасса ОБЯЗАНА быть. Список ЗАКРЫТЫЙ, и граница проведена по
# тому, КТО трассу пишет, а не по расплывчатому «проба не прошла»: пишет её ветка
# «исход не совпал с ожидаемым» в разборе фикстуры `page`. Поэтому сюда не входят
#   * passed      — архив прошедшей пробы не нужен и НАМЕРЕННО не пишется;
#   * skipped     — фикстура либо не разворачивалась вовсе (проба не стартовала
#                   при ранней остановке), либо исход совпал с ожидаемым;
#   * interrupted — разбор оборван вместе с прогоном, дописывать архив нечем.
# Включить их значило бы завести проверку, чьи находки ложны все до одной, — а
# такую перестают читать, и вместе с ней перестают читать настоящую.
TRACE_EXPECTED = ("failed", "timedOut")


class Probe(NamedTuple):
    """Запись пробы из отчёта.

    Заведена вместо четвёрки-кортежа, когда к исходу добавились ИМЕНА ВЛОЖЕНИЙ
    (#1287): пятое поле кортежа читалось бы как `g[4]`, а по такому индексу
    следующая правка ошибётся молча.
    """

    title: str
    status: str
    message: str
    runs: int
    attachments: tuple[str, ...]
    # Проект прогонщика (`projectName` отчёта). Пусто у отчёта без проектов.
    project: str = ""


def declared_probes(specs_dir: Path, glob: str = SPECS_GLOB) -> tuple[int, int]:
    """Сколько объявлений в дереве и сколько файлов для этого прочитано."""
    files = sorted(specs_dir.glob(glob)) if specs_dir.is_dir() else []
    return sum(len(DECL.findall(f.read_text(encoding="utf-8"))) for f in files), len(files)


def walk_specs(node: dict) -> list[dict]:
    """Плоский список записей проб из отчёта playwright (вложенность произвольна)."""
    out: list[dict] = []
    for spec in node.get("specs", []) or []:
        out.append(spec)
    for child in node.get("suites", []) or []:
        out.extend(walk_specs(child))
    return out


def outcomes(report: dict) -> list[Probe]:
    """Записи проб: имя, исход, текст отказа, число запусков, имена вложений.

    Текст нужен третьей категории (#935): падение НА НАВИГАЦИИ означает, что
    проба до продукта не дошла, и вердикт о продукте по ней не выносится.

    Число запусков — ЕДИНСТВЕННЫЙ признак, отличающий пробу, которая не
    стартовала вовсе (прогон остановился раньше неё), от намеренного
    `test.skip`: исход у обеих один и тот же — `skipped`, — а запусков у первой
    НОЛЬ, у второй ровно один. Признак замерен на playwright 1.56.1, а не
    выведен из документации: сравнивать пришлось два отчёта, отличающихся
    только этим (#1050).

    Вложения берутся из ТОГО ЖЕ запуска, чей исход попал в `status` (#1287):
    трасса принадлежит попытке, а не пробе, и при повторах их было бы несколько.
    Повторов здесь нет (`retries: 0`), но привязка к последнему запуску делает
    свойство верным и без этой оговорки.
    """
    res: list[Probe] = []
    for spec in walk_specs(report):
        title = spec.get("title") or "(без имени)"
        status = "не исполнена"
        message = ""
        started = 0
        attached: tuple[str, ...] = ()
        project = ""
        for t in spec.get("tests", []) or []:
            project = t.get("projectName") or project
            runs = t.get("results", []) or []
            started += len(runs)
            if runs:
                last = runs[-1]
                status = last.get("status") or "не исполнена"
                attached = tuple(
                    (a or {}).get("name") or "" for a in (last.get("attachments") or [])
                )
                # САМЫЙ СОДЕРЖАТЕЛЬНЫЙ из доступных текстов, а не первый.
                # Замерено (#1050): при снятии пробы по времени `error.message`
                # несёт голое «Test timeout of Nms exceeded», а журнал ожидания
                # с ИМЕНЕМ ЛОКАТОРА лежит во ВТОРОЙ записи `errors[]`. Взяв
                # первую, гейт печатает диагноз, по которому ничего не
                # разобрать, — то есть выполняет форму и не даёт содержания.
                candidates = [(last.get("error") or {}).get("message") or ""]
                candidates += [
                    (e or {}).get("message") or "" for e in (last.get("errors") or [])
                ]
                message = max(candidates, key=len, default="")
            elif t.get("status"):
                status = t["status"]
        res.append(Probe(title, status, message, started, attached, project))
    return res


# Отказы, при которых запрос до продукта НЕ ДОШЁЛ: имя не разрешилось, соединение
# отвергнуто, стенд недостижим. Список закрытый и узкий намеренно — расширять его
# «похожими» словами значит превращать третью категорию в маску для красного.
_UNREACHED = (
    "net::ERR_NAME_NOT_RESOLVED",
    "net::ERR_CONNECTION_REFUSED",
    "net::ERR_CONNECTION_RESET",
    "net::ERR_ADDRESS_UNREACHABLE",
)


def unreached(message: str) -> bool:
    return any(tok in message for tok in _UNREACHED)


def verdict(report_path: Path, specs_dir: Path, preconditions_dir: Path | None = None) -> tuple[int, list[str]]:
    """Возвращает (код возврата, строки вывода)."""
    log: list[str] = []
    declared, files = declared_probes(specs_dir)
    log.append(f"=== осмотрено: исходников проб {files}, объявлений в них {declared} ===")
    if files == 0 or declared == 0:
        log.append(
            "ПРОВАЛ: в дереве не найдено ни одного объявления пробы. Гейт судил бы о "
            "наборе, которого не читал, и его «ноль упавших» означало бы «ноль "
            f"прочитанного». Каталог: {specs_dir}"
        )
        return 1, log

    if not report_path.exists():
        log.append(
            f"ПРОВАЛ: отчёта нет ({report_path}). Суита без отчёта НЕ ВЫПОЛНИЛАСЬ — это "
            "третья категория исхода, и она не вычитается из вердикта и не зачитывается "
            "в зелёное."
        )
        return 1, log

    try:
        report = json.loads(report_path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        log.append(f"ПРОВАЛ: отчёт не разбирается ({exc}) — исход прогона неизвестен.")
        return 1, log

    records = outcomes(report)
    # Записи УСЛОВИЙ отделяются от записей проб по имени проекта: условие — не
    # проба о продукте, и ни в счёт проб, ни в перепись трассы оно не входит.
    conditions = [r for r in records if r.project == PRECONDITION_PROJECT]
    got = [r for r in records if r.project != PRECONDITION_PROJECT]
    started = [g for g in got if g.runs > 0]
    not_started = [g for g in got if g.runs == 0]
    declared_conditions, condition_files = (
        declared_probes(preconditions_dir, PRECONDITIONS_GLOB) if preconditions_dir else (0, 0)
    )
    created = [c for c in conditions if c.status == "passed"]
    log.append(f"=== разобрано записей отчёта: {len(records)}, из них проб {len(got)} ===")
    log.append(f"=== исполнено проб {len(started)} из {declared} объявленных ===")
    log.append(
        f"=== условий прогона {len(conditions)}, создано {len(created)} "
        f"(объявлений условий {declared_conditions} в {condition_files} файлах) ==="
    )
    rc = 0

    if len(got) != declared:
        log.append(
            f"ПРОВАЛ: объявлено проб {declared}, в отчёте {len(got)}. Расхождение значит, "
            "что часть проб не исполнялась, а прогон об этом молчал: «ноль упавших» из "
            "двух и из семи выглядит одинаково."
        )
        rc = 1

    if len(conditions) != declared_conditions:
        log.append(
            f"ПРОВАЛ: условий объявлено {declared_conditions}, в отчёте {len(conditions)}. "
            "Условие, выпавшее из прогона, уносит с собой различение «не выполнилось» и "
            "«красное»: зависящие от него пробы судили бы посадку, которой не спрашивали."
        )
        rc = 1

    bad = [g for g in got if g.status != "passed"]
    bad_started = [g for g in got if g.status != "passed" and g.runs > 0]
    for g in got:
        mark = "✓" if g.status == "passed" else ("·" if g.runs == 0 else "✗")
        shown = "не стартовала" if g.runs == 0 else g.status
        log.append(f"  {mark} {shown:<14} {g.title}")

    # ─── ТРЕТЬЕ УТВЕРЖДЕНИЕ: У УПАВШЕЙ ПРОБЫ ЕСТЬ ТРАССА (#1287) ─────────────
    #
    # Текст отказа говорит, ЧТО не сошлось; трасса — что происходило в браузере
    # до этого. Без неё разбор красного ведётся по имени шага, то есть вслепую,
    # и потеря эта ТИХАЯ: код возврата прогона о вложениях не знает, а гейт до
    # сих пор смотрел только на исходы. Одну такую потерю (#1242) нашли ВРУЧНУЮ
    # — только потому, что кто-то попытался открыть файл. Механизм той потери
    # закрыт отдельно, но класс шире одного механизма: артефакт теряется и по
    # другим причинам, а вердикт оставался зелёным по своей части.
    #
    # ПЕЧАТАЮТСЯ ДВА ЧИСЛА, а не одно. «Без трассы 0» само по себе неотличимо от
    # «упавших не было вовсе»: первое — свойство прогона, второе — отсутствие
    # предмета. Разделяет их только пара «с трассой N, без трассы M», и печатать
    # её надо ВСЕГДА, в том числе на полностью зелёном прогоне.
    #
    # Строка стоит ВЫШЕ ранних возвратов намеренно: перепись обязана печататься и
    # тогда, когда исход прогона относят к третьей категории. Код возврата в тех
    # ветках остаётся за КАТЕГОРИЕЙ ИСХОДА — если до продукта не дошла ни одна
    # проба, разбирать надо достижимость стенда, а находка о трассе своё место в
    # журнале уже заняла и никуда из него не денется.
    need_trace = [g for g in got if g.runs > 0 and g.status in TRACE_EXPECTED]
    lost_trace = [g for g in need_trace if TRACE_ATTACHMENT not in g.attachments]
    log.append(
        f"=== трасса: упавших проб {len(need_trace)}, "
        f"с трассой {len(need_trace) - len(lost_trace)}, без трассы {len(lost_trace)} ==="
    )
    for g in lost_trace:
        shown = ", ".join(a for a in g.attachments if a) or "ни одного"
        log.append(
            f"ПРОВАЛ: у упавшей пробы нет вложения «{TRACE_ATTACHMENT}»: {g.title} "
            f"(исход: {g.status}; вложений в отчёте: {shown})"
        )
    if lost_trace:
        log.append(
            "  Разбирать такое красное придётся по имени шага и тексту отказа — без "
            "записи того, что происходило в браузере, то есть без единственного "
            "артефакта, ради которого трассу и включают."
        )
        rc = 1

    # ТРЕТЬЯ КАТЕГОРИЯ (#2780, приёмка F8 §4): УСЛОВИЕ ПРОГОНА НЕ СОЗДАНО.
    #
    # Упавшее условие — положительное и конкретное свидетельство: его запись
    # принадлежит проекту условий, и зависящие от него пробы не стартовали вовсе.
    # Исход отчитывается ЧИСЛОМ сценариев без вердикта, как требует приёмка, а не
    # красным и не зелёным. Но ровно в двух случаях он третьей категорией НЕ
    # становится:
    #   * независимая проба упала по существу — красное о продукте ПЕРЕВЕШИВАЕТ,
    #     иначе несозданное условие одной части набора прятало бы дефект другой;
    #   * не стартовавших проб нет — зависимость проектов не провязана, и пробы,
    #     которым условие нужно, судили посадку, которую предмет не поддерживает.
    failed_conditions = [c for c in conditions if c.status != "passed"]
    if failed_conditions:
        for c in failed_conditions:
            log.append(f"условие прогона НЕ создано: {c.title}")
            for line in plain(c.message or "(текст отказа пуст)").strip().splitlines()[:6]:
                log.append(f"    {line}")
        waiting = not_started
        if not waiting:
            log.append(
                "ПРОВАЛ: условие прогона не создано, а пробы исполнялись все до одной — "
                "зависимость проектов от условия не провязана (`dependencies` в "
                "playwright.config.ts). Их вердикт вынесен о посадке, которой предмет не "
                "поддерживает, и не зачитывается ни в зелёное, ни в «не выполнилось»."
            )
            return RC_RED, log
        log.append(
            f"  сценариев без вердикта {len(waiting)} из {declared}; исполнено независимых "
            f"{len(started)}, из них не прошли {len(bad_started)}"
        )
        if bad_started or rc:
            log.append(
                f"ПРОВАЛ: проб не в состоянии «прошла» среди исполненных: {len(bad_started)}. "
                "Красное о продукте перевешивает несозданное условие: иначе условие одной "
                "части набора прятало бы дефект другой."
            )
            return RC_RED, log
        log.append(
            f"НЕ ВЫПОЛНИЛОСЬ: условие прогона не создано — сценариев без вердикта "
            f"{len(waiting)} из {declared}. Это НЕ вердикт о продукте: разбирать надо "
            "посадку, на которой гоняли пробы (приёмка F8, §4), а не консоль. Третья "
            "категория из вердикта не вычитается и в зелёное не зачитывается."
        )
        return RC_UNMET, log

    # ТРЕТЬЯ КАТЕГОРИЯ (#935): ни одна проба не дошла до продукта.
    #
    # Красное означает «продукт ответил не то». Если КАЖДАЯ упавшая проба
    # отвалилась на самой навигации — стенд недостижим для браузера, и о
    # продукте не сказано ничего. Код возврата остаётся ненулевым (вычета нет,
    # прогон не зелёный), но причина названа своя: иначе разбор уходит в
    # продукт, которого запрос не касался.
    if bad_started and len(bad_started) == len(started) and all(
        unreached(g.message) for g in bad_started
    ):
        log.append(
            f"НЕ ВЫПОЛНИЛОСЬ: все {len(started)} стартовавших проб отвалились на навигации — до "
            "продукта не дошла ни одна. Это НЕ вердикт по продукту: разбирать "
            "надо достижимость стенда для браузера. Шаг «браузер видит консоль» "
            "задаёт тот же вопрос ДО прогона и обязан был поймать это раньше."
        )
        return RC_UNMET, log

    # ТРЕТЬЯ КАТЕГОРИЯ: прогон ОСТАНОВИЛСЯ САМ, не дойдя до конца набора (#1050).
    #
    # Проба с нулём запусков не стартовала вовсе. Это ни «пропуск» (тот несёт
    # ровно один запуск с исходом `skipped` — и остаётся провалом), ни «выпала
    # из набора» (той нет в отчёте совсем — это ловит сверка числа выше). Это
    # набор, не исполненный целиком, и вердикта по продукту у непрогнанных проб
    # нет: зелёным такой исход не становится, но и красным ПО ПРОДУКТУ не
    # называется — иначе разбор уйдёт в продукт, которого проба не касалась.
    if not_started:
        cap = (report.get("config") or {}).get("maxFailures") or 0
        first = next((g for g in got if g.runs > 0 and g.status != "passed"), None)
        log.append(
            f"НЕ ВЫПОЛНИЛОСЬ: исполнено {len(started)} проб из {declared} "
            f"объявленных, не стартовало {len(not_started)}. Прогон остановлен "
            f"ранней остановкой (предел падений: {cap or 'не объявлен'}). Набор "
            "не исполнен целиком — это ТРЕТЬЯ категория исхода, она не "
            "вычитается из вердикта и не зачитывается в зелёное."
        )
        if first:
            log.append(f"  диагноз — первое падение: {first.title}")
            for line in plain(first.message or "(текст отказа пуст)").strip().splitlines()[:6]:
                log.append(f"    {line}")
        else:
            log.append(
                "  диагноз назвать НЕЧЕМ: ни одна стартовавшая проба не упала, "
                "а прогон всё же оборвался — разбирать надо сам прогон."
            )
        return 1, log

    if bad:
        log.append(f"ПРОВАЛ: проб не в состоянии «прошла»: {len(bad)}.")
        log.append(
            "  Пропуск здесь — тоже провал: пропущенная проба это отсутствующая проверка."
        )
        rc = 1

    if rc == 0:
        log.append(f"✓ исполнены все {declared} объявленных проб, упавших и пропущенных нет")
    return rc, log


# ─────────────────────────────────────────────────────────────────────────────
# САМОПРОВЕРКА: гейт обязан покраснеть на настоящем дефекте и смолчать на
# законном близнеце. Не доказавший обоих — не доказательство.
# ─────────────────────────────────────────────────────────────────────────────

_SPEC = 'test("одна", async () => {});\ntest("две", async () => {});\n'
_SPEC_WITH_GROUP = (
    'test.describe("группа", () => {\n  test("три", async () => {});\n});\n'
)


def _trace_attachments() -> list[dict]:
    """Вложение трассы в той же форме, в какой его пишет прогонщик."""
    return [{
        "name": TRACE_ATTACHMENT,
        "contentType": "application/zip",
        "path": "/tmp/test-results/x/trace.zip",
    }]


def _spec(title: str, status: str, message: str = "", runs: int = 1,
          trace: bool | None = None, project: str = "probes") -> dict:
    """Запись пробы. `runs=0` — проба не стартовала (ранняя остановка прогона
    либо несозданное условие, от которого зависит её проект);
    `runs=1, status="skipped"` — намеренный `test.skip`. Различие замерено на
    настоящем отчёте playwright, а не придумано (#1050).

    `trace` по умолчанию воспроизводит ФАКТИЧЕСКОЕ поведение набора: упавшая
    проба несёт вложение трассы, прошедшая — нет. Это делает все прежние
    фикстуры ЗАКОННЫМИ близнецами для проверки трассы (#1287): инъекция обязана
    ронять только своё, иначе красное придёт от соседа и вакуумность новой
    проверки останется незамеченной. `trace=False` — сама инъекция.

    `project` — имя проекта прогонщика, как его кладёт отчёт (`projectName`).
    Форма отчёта с проектом-условием замерена на playwright 1.56.1 (#2780):
    проба зависимого проекта при упавшем условии приходит `skipped` с НУЛЁМ
    запусков, а само условие — записью своего проекта с исходом `failed`."""
    keep = (status in TRACE_EXPECTED) if trace is None else trace
    t: dict = {"status": status, "results": [], "projectName": project}
    if runs:
        res: dict = {"status": status, "error": {"message": message}}
        if keep:
            res["attachments"] = _trace_attachments()
        t["results"] = [res]
    return {"title": title, "tests": [t]}


def _condition(status: str, message: str = "") -> dict:
    """Запись условия прогона. Браузера условие не открывает, поэтому трассы у
    него нет by construction — и на падении тоже."""
    return _spec("условие прогона", status, message, trace=False, project=PRECONDITION_PROJECT)


def _report_of(*specs: dict, max_failures: int = 0) -> str:
    return json.dumps({
        "config": {"maxFailures": max_failures},
        "suites": [{"title": "s", "specs": list(specs)}],
    })


def _report(*statuses: str, message: str = "") -> str:
    """Отчёт из исходов. Трасса проставляется по тому же правилу, что в `_spec`."""
    return json.dumps({"suites": [{"title": "s", "specs": [
        _spec(f"проба-{i}", st, message) for i, st in enumerate(statuses)
    ]}]})


def self_test() -> int:
    rc = 0
    cases: list[tuple[str, bool, object, object]] = []

    with tempfile.TemporaryDirectory() as tmp:
        root = Path(tmp)
        specs = root / "specs"
        specs.mkdir()
        (specs / "a.spec.ts").write_text(_SPEC, encoding="utf-8")
        (specs / "b.spec.ts").write_text(_SPEC_WITH_GROUP, encoding="utf-8")
        # Объявлено 3: две на верхнем уровне и одна внутри группы. Сама группа
        # (`test.describe(`) пробой не считается — иначе законный близнец
        # завышал бы объявленное и гейт краснел бы на исправном прогоне.
        declared, _ = declared_probes(specs)
        cases.append(("объявленное считается по дереву", declared == 3, 3, declared))

        rep = root / "results.json"

        # МОЛЧИТ: исполнено всё объявленное, все прошли.
        rep.write_text(_report("passed", "passed", "passed"), encoding="utf-8")
        got, _ = verdict(rep, specs)
        cases.append(("законный прогон принят", got == 0, 0, got))

        # КРАСНЕЕТ: одна проба упала.
        rep.write_text(_report("passed", "failed", "passed"), encoding="utf-8")
        got, _ = verdict(rep, specs)
        cases.append(("упавшая проба ловится", got == 1, 1, got))

        # КРАСНЕЕТ: проба пропущена — отсутствующая проверка, а не «не считается».
        rep.write_text(_report("passed", "passed", "skipped"), encoding="utf-8")
        got, _ = verdict(rep, specs)
        cases.append(("пропуск ловится", got == 1, 1, got))

        # КРАСНЕЕТ: проба молча выпала из набора. Ровно тот случай, ради которого
        # гейт и существует: код возврата прогона здесь был бы нулевым.
        rep.write_text(_report("passed", "passed"), encoding="utf-8")
        got, _ = verdict(rep, specs)
        cases.append(("недосчёт исполненного ловится", got == 1, 1, got))

        # КРАСНЕЕТ: отчёта нет вовсе — «не выполнилось» не зачитывается в зелёное.
        rep.unlink()
        got, _ = verdict(rep, specs)
        cases.append(("отсутствие отчёта ловится", got == 1, 1, got))

        # ТРЕТЬЯ КАТЕГОРИЯ: все пробы отвалились на навигации — вердикт остаётся
        # ненулевым (вычета нет), но причина названа своя.
        rep.write_text(
            _report("failed", "failed", "failed",
                    message="page.goto: net::ERR_NAME_NOT_RESOLVED at http://x/"),
            encoding="utf-8",
        )
        got, log = verdict(rep, specs)
        cases.append(("недостижимость названа своей причиной",
                      got == RC_UNMET and any("НЕ ВЫПОЛНИЛОСЬ" in ln for ln in log),
                      f"{RC_UNMET} + «НЕ ВЫПОЛНИЛОСЬ»", got))
        cases.append(("недостижимость даёт СВОЙ код, отличный от красного",
                      got != RC_RED and got != RC_GREEN, f"не {RC_RED} и не {RC_GREEN}", got))

        # ЗАКОННЫЙ БЛИЗНЕЦ: те же три падения, но по существу продукта — третья
        # категория объявляться НЕ должна, иначе она станет маской для красного.
        rep.write_text(
            _report("failed", "failed", "failed",
                    message="expect(received).toBeVisible() — элемент не найден"),
            encoding="utf-8",
        )
        got, log = verdict(rep, specs)
        cases.append(("падение по существу третьей категорией НЕ считается",
                      got == RC_RED and not any("НЕ ВЫПОЛНИЛОСЬ" in ln for ln in log),
                      f"{RC_RED} без «НЕ ВЫПОЛНИЛОСЬ»", got))

        # ЗАКОННЫЙ БЛИЗНЕЦ: часть проб дошла до продукта — значит стенд достижим,
        # и сетевое падение остальных третьей категорией не объявляется.
        rep.write_text(
            json.dumps({"suites": [{"title": "s", "specs": [
                {"title": "прошла", "tests": [{"results": [{"status": "passed"}]}]},
                {"title": "упала", "tests": [{"results": [
                    {"status": "failed",
                     "error": {"message": "net::ERR_NAME_NOT_RESOLVED"},
                     "attachments": _trace_attachments()}]}]},
                {"title": "прошла-2", "tests": [{"results": [{"status": "passed"}]}]},
            ]}]}),
            encoding="utf-8",
        )
        got, log = verdict(rep, specs)
        # ПРОТИВОПОЛОЖНАЯ ИНЪЕКЦИЯ (#1041): одиночная сетевая ошибка при прочих
        # зелёных обязана остаться КРАСНОЙ и получить код красного. Иначе
        # послабление становится маской: любой сетевой сбой одной пробы уводил бы
        # весь прогон в «условие не создано».
        cases.append(("частичная недостижимость третьей категорией НЕ считается",
                      got == RC_RED and not any("НЕ ВЫПОЛНИЛОСЬ" in ln for ln in log),
                      f"{RC_RED} без «НЕ ВЫПОЛНИЛОСЬ»", got))

        # ТРЕТЬЯ КАТЕГОРИЯ (#1050): прогон остановился сам, не дойдя до конца
        # набора. Гейт обязан назвать исход «не выполнилось» И дать диагноз —
        # текст первого падения. Без диагноза ранняя остановка не лучше снятия
        # по времени: отчёт есть, а разбирать по нему нечего.
        rep.write_text(
            _report_of(
                _spec("упала-1", "failed", 'waiting for locator("input[name=x]")'),
                _spec("упала-2", "failed", 'waiting for locator("input[name=x]")'),
                _spec("не-стартовала", "skipped", runs=0),
                max_failures=2,
            ),
            encoding="utf-8",
        )
        got, log = verdict(rep, specs)
        joined = "\n".join(log)
        cases.append((
            "ранняя остановка названа третьей категорией",
            got == 1 and "НЕ ВЫПОЛНИЛОСЬ: исполнено 2 проб из 3" in joined,
            "1 + «исполнено 2 из 3»", got))
        cases.append((
            "ранняя остановка несёт ДИАГНОЗ первого падения",
            'waiting for locator("input[name=x]")' in joined,
            "текст первого отказа в выводе", "нет" if 'locator' not in joined else "есть"))
        cases.append((
            "ранняя остановка называет объявленный предел",
            "предел падений: 2" in joined, "предел падений: 2",
            "назван" if "предел падений: 2" in joined else "НЕ назван"))

        # ДИАГНОЗ БЕРЁТСЯ САМЫЙ СОДЕРЖАТЕЛЬНЫЙ, а не первый: при снятии по
        # времени имя локатора лежит во второй записи `errors[]`, и гейт,
        # печатающий первую, даёт форму без содержания. Цвет снимается.
        rep.write_text(
            json.dumps({
                "config": {"maxFailures": 1},
                "suites": [{"title": "s", "specs": [
                    {"title": "снята по времени", "tests": [{"status": "timedOut", "results": [{
                        "status": "timedOut",
                        "attachments": _trace_attachments(),
                        "error": {"message": "\x1b[31mTest timeout of 10000ms exceeded.\x1b[39m"},
                        "errors": [
                            {"message": "Test timeout of 10000ms exceeded."},
                            {"message": 'Error: page.fill: Test timeout.\nCall log:\n  - waiting for locator(\'input[name="traits.email"]\')'},
                        ],
                    }]}]},
                    {"title": "не-стартовала", "tests": [{"status": "skipped", "results": []}]},
                ]}],
            }),
            encoding="utf-8",
        )
        got, log = verdict(rep, specs)
        joined = "\n".join(log)
        cases.append((
            "диагноз берёт самый содержательный текст, а не первый",
            'waiting for locator' in joined,
            "имя локатора в выводе",
            "есть" if 'waiting for locator' in joined else "НЕТ"))
        cases.append((
            "цвет из чужого вывода снят",
            "\x1b[" not in joined, "без управляющих последовательностей",
            "чисто" if "\x1b[" not in joined else "остались"))

        # ЗАКОННЫЙ БЛИЗНЕЦ: намеренный `test.skip` несёт РОВНО ОДИН запуск.
        # Он остаётся провалом (отсутствующая проверка) и третьей категорией
        # НЕ объявляется — иначе ранняя остановка станет маской для пропусков.
        rep.write_text(
            _report_of(
                _spec("прошла", "passed"),
                _spec("намеренно пропущена", "skipped"),
                _spec("прошла-2", "passed"),
            ),
            encoding="utf-8",
        )
        got, log = verdict(rep, specs)
        joined = "\n".join(log)
        cases.append((
            "намеренный пропуск третьей категорией НЕ считается",
            got == 1 and "НЕ ВЫПОЛНИЛОСЬ" not in joined,
            "1 без «НЕ ВЫПОЛНИЛОСЬ»", got))

        # ЗАКОННЫЙ БЛИЗНЕЦ: полный зелёный прогон — перепись исполненного
        # печатается и здесь, иначе «ноль находок» неотличимо от «ноль
        # прочитанного».
        rep.write_text(
            _report_of(_spec("а", "passed"), _spec("б", "passed"), _spec("в", "passed")),
            encoding="utf-8",
        )
        got, log = verdict(rep, specs)
        joined = "\n".join(log)
        cases.append((
            "перепись исполненного печатается и на зелёном",
            got == 0 and "исполнено проб 3 из 3" in joined,
            "0 + «исполнено проб 3 из 3»", got))

        # ─── ТРАССА УПАВШЕЙ ПРОБЫ (#1287) ────────────────────────────────
        #
        # ТРИ ПРОГОНА, а не два, и причина не в осторожности. Упавшая проба
        # КРАСНА САМА ПО СЕБЕ — существующим утверждением об исходе, — поэтому по
        # КОДУ ВОЗВРАТА новую проверку от старой не отличить ни при какой
        # инъекции: обе дают единицу. Отличает их ЖУРНАЛ — пара чисел переписи и
        # строка находки с именем пробы. Отсюда:
        #   (1) КОНТРОЛЬ — всё цело: молчат оба, перепись объявляет отсутствие
        #       предмета парой нулей;
        #   (2) ИНЪЕКЦИЯ НОВОГО — у упавшей пробы снято ТОЛЬКО вложение трассы,
        #       больше ничего: красное обязано прийти С ИМЕНЕМ пробы;
        #   (3) ИНЪЕКЦИЯ СУЩЕСТВУЮЩЕГО — та же упавшая проба, но С трассой:
        #       старое утверждение краснеет, новое обязано МОЛЧАТЬ. Без третьего
        #       прогона молчание новой проверки неотличимо от её мёртвости.

        # (1) КОНТРОЛЬ. Он же — проверка на ПУСТОМ входе: прогон без единой
        # упавшей пробы это ЦЕЛЬ, а не поломка, и перепись обязана печататься
        # именно здесь, иначе «без трассы 0» неотличимо от «не смотрели».
        rep.write_text(
            _report_of(_spec("а", "passed"), _spec("б", "passed"), _spec("в", "passed")),
            encoding="utf-8",
        )
        got, log = verdict(rep, specs)
        joined = "\n".join(log)
        census = next((ln for ln in log if ln.startswith("=== трасса")), "строки нет")
        cases.append((
            "контроль: перепись трассы печатается и без единой упавшей пробы",
            got == 0 and "трасса: упавших проб 0, с трассой 0, без трассы 0" in joined,
            "0 + «упавших проб 0, с трассой 0, без трассы 0»", f"{got} / {census}"))

        # (2) ИНЪЕКЦИЯ НОВОГО.
        rep.write_text(
            _report_of(_spec("а", "passed"),
                       _spec("трасса потеряна", "failed", "expect(x).toBeVisible()",
                             trace=False),
                       _spec("в", "passed")),
            encoding="utf-8",
        )
        got, log = verdict(rep, specs)
        joined = "\n".join(log)
        census = next((ln for ln in log if ln.startswith("=== трасса")), "строки нет")
        cases.append((
            "потеря трассы у упавшей пробы ловится",
            got == 1 and "нет вложения «trace»" in joined,
            "1 + «нет вложения «trace»»", got))
        cases.append((
            "находка называет КООРДИНАТУ — имя пробы",
            "трасса потеряна" in joined, "имя пробы в выводе",
            "названо" if "трасса потеряна" in joined else "НЕ названо"))
        cases.append((
            "перепись называет ОБА числа, а не одно",
            "трасса: упавших проб 1, с трассой 0, без трассы 1" in joined,
            "«упавших проб 1, с трассой 0, без трассы 1»", census))

        # (3) ИНЪЕКЦИЯ СУЩЕСТВУЮЩЕГО: та же проба, но трасса на месте.
        rep.write_text(
            _report_of(_spec("а", "passed"),
                       _spec("упала честно", "failed", "expect(x).toBeVisible()"),
                       _spec("в", "passed")),
            encoding="utf-8",
        )
        got, log = verdict(rep, specs)
        joined = "\n".join(log)
        census = next((ln for ln in log if ln.startswith("=== трасса")), "строки нет")
        cases.append((
            "упавшая проба С трассой: СТАРОЕ утверждение краснеет",
            got == 1 and "проб не в состоянии «прошла»: 1" in joined,
            "1 + «проб не в состоянии «прошла»: 1»", got))
        cases.append((
            "упавшая проба С трассой: НОВОЕ утверждение молчит",
            "нет вложения" not in joined
            and "трасса: упавших проб 1, с трассой 1, без трассы 0" in joined,
            "«с трассой 1, без трассы 0» и ни одной находки", census))

        # ЗАКОННЫЙ БЛИЗНЕЦ: намеренный пропуск. Фикстура до своего разбора не
        # дошла, трассы нет by construction. Провал по ПРОПУСКУ остаётся,
        # находки о трассе быть не должно.
        rep.write_text(
            _report_of(_spec("а", "passed"), _spec("пропущена", "skipped"),
                       _spec("в", "passed")),
            encoding="utf-8",
        )
        got, log = verdict(rep, specs)
        joined = "\n".join(log)
        census = next((ln for ln in log if ln.startswith("=== трасса")), "строки нет")
        cases.append((
            "пропуск трассы НЕ требует",
            got == 1 and "нет вложения" not in joined
            and "трасса: упавших проб 0, с трассой 0, без трассы 0" in joined,
            "1 по пропуску, ноль находок о трассе", census))

        # ЗАКОННЫЙ БЛИЗНЕЦ: проба, не стартовавшая вовсе (ранняя остановка).
        # Фикстура не разворачивалась — спрашивать с неё артефакт не с чего;
        # с двух УПАВШИХ рядом он спрашивается и находится.
        rep.write_text(
            _report_of(_spec("упала-1", "failed", "x"),
                       _spec("упала-2", "failed", "x"),
                       _spec("не-стартовала", "skipped", runs=0),
                       max_failures=2),
            encoding="utf-8",
        )
        got, log = verdict(rep, specs)
        joined = "\n".join(log)
        census = next((ln for ln in log if ln.startswith("=== трасса")), "строки нет")
        cases.append((
            "не стартовавшая проба трассы НЕ требует",
            "нет вложения" not in joined
            and "трасса: упавших проб 2, с трассой 2, без трассы 0" in joined,
            "«упавших проб 2, с трассой 2, без трассы 0»", census))

        # ГРАНИЦА: снятие по времени — тоже падение, и трасса с него
        # спрашивается. Ровно этим исходом отвечал прогон в #1242.
        rep.write_text(
            _report_of(_spec("а", "passed"),
                       _spec("снята по времени", "timedOut",
                             "Test timeout of 90000ms exceeded", trace=False),
                       _spec("в", "passed")),
            encoding="utf-8",
        )
        got, log = verdict(rep, specs)
        cases.append((
            "снятая по времени проба тоже обязана нести трассу",
            got == 1 and any("нет вложения «trace»" in ln for ln in log),
            "1 + находка", got))

        # ГРАНИЦА С ДРУГОЙ СТОРОНЫ: прогон оборван, разбор фикстуры оборван
        # вместе с ним, дописывать архив нечем. Требовать трассу здесь значило бы
        # краснеть на исправном прогоне — то есть завести проверку, чьи находки
        # ложны все до одной.
        rep.write_text(
            _report_of(_spec("а", "passed"),
                       _spec("оборвана", "interrupted", trace=False),
                       _spec("в", "passed")),
            encoding="utf-8",
        )
        got, log = verdict(rep, specs)
        joined = "\n".join(log)
        census = next((ln for ln in log if ln.startswith("=== трасса")), "строки нет")
        cases.append((
            "оборванная проба трассы НЕ требует",
            "нет вложения" not in joined
            and "трасса: упавших проб 0, с трассой 0, без трассы 0" in joined,
            "ноль находок о трассе", census))

        # ─── УСЛОВИЕ ПРОГОНА — ОТДЕЛЬНЫЙ ПРОЕКТ ПРОГОНЩИКА (#2780, F8 §4) ───
        #
        # Условие, без которого часть набора не исполнима, объявлено СВОЕЙ записью
        # в каталоге условий, а зависящие от него пробы — проектом, который от
        # него зависит. Упало условие — зависящие не стартуют вовсе (ноль
        # запусков), и это ТРЕТЬЯ категория с числом сценариев, а не красное о
        # продукте. Каждая инъекция ниже меняет ровно один факт против законного
        # прогона с созданным условием.
        conds = root / "preconditions"
        conds.mkdir()
        (conds / "landing.precondition.ts").write_text(
            'test("условие", async () => {});\n', encoding="utf-8")

        # КОНТРОЛЬ: условие создано, всё объявленное исполнено и прошло.
        rep.write_text(
            _report_of(_condition("passed"),
                       _spec("а", "passed"), _spec("б", "passed"), _spec("в", "passed")),
            encoding="utf-8",
        )
        got, log = verdict(rep, specs, conds)
        joined = "\n".join(log)
        cases.append((
            "условие создано: законный прогон принят, перепись условий печатается",
            got == RC_GREEN and "условий прогона 1, создано 1" in joined,
            f"{RC_GREEN} + «условий прогона 1, создано 1»", got))

        # ИНЪЕКЦИЯ: условие не создано — зависящие пробы не стартовали.
        rep.write_text(
            _report_of(_condition("failed", "УСЛОВИЕ ПРОГОНА НЕ СОЗДАНО: /login отдаёт не оболочку"),
                       _spec("F8-01 а", "skipped", runs=0),
                       _spec("F8-02 б", "skipped", runs=0),
                       _spec("F8-03 в", "skipped", runs=0)),
            encoding="utf-8",
        )
        got, log = verdict(rep, specs, conds)
        joined = "\n".join(log)
        cases.append((
            "несозданное условие — третья категория со СВОИМ кодом",
            got == RC_UNMET, RC_UNMET, got))
        cases.append((
            "третья категория названа ЧИСЛОМ сценариев без вердикта",
            "НЕ ВЫПОЛНИЛОСЬ: условие прогона не создано" in joined
            and "сценариев без вердикта 3 из 3" in joined,
            "«условие прогона не создано» + «сценариев без вердикта 3 из 3»",
            "есть" if "сценариев без вердикта 3 из 3" in joined else "нет"))
        cases.append((
            "причина условия приезжает в журнал дословно",
            "/login отдаёт не оболочку" in joined, "текст отказа условия",
            "есть" if "/login отдаёт не оболочку" in joined else "нет"))
        cases.append((
            "у условия трассы не спрашивают — браузера оно не открывает",
            "нет вложения" not in joined, "ни одной находки о трассе",
            "чисто" if "нет вложения" not in joined else "находка"))

        # ЗАКОННЫЙ БЛИЗНЕЦ: условие создано, одна проба упала по существу —
        # красное о продукте, третьей категорией НЕ называется.
        rep.write_text(
            _report_of(_condition("passed"),
                       _spec("а", "passed"),
                       _spec("б", "failed", "expect(locator).toBeVisible() — экран не отрисован"),
                       _spec("в", "passed")),
            encoding="utf-8",
        )
        got, log = verdict(rep, specs, conds)
        joined = "\n".join(log)
        cases.append((
            "условие создано, проба упала — красное о продукте",
            got == RC_RED and "НЕ ВЫПОЛНИЛОСЬ" not in joined,
            f"{RC_RED} без «НЕ ВЫПОЛНИЛОСЬ»", got))

        # ИНЪЕКЦИЯ: условие не создано, а пробы ИСПОЛНЯЛИСЬ — зависимость
        # проектов не провязана. Их вердикт вынесен о посадке, которую предмет не
        # поддерживает, и зачесть его нельзя ни в зелёное, ни в третью категорию.
        rep.write_text(
            _report_of(_condition("failed", "УСЛОВИЕ ПРОГОНА НЕ СОЗДАНО"),
                       _spec("а", "passed"), _spec("б", "passed"), _spec("в", "passed")),
            encoding="utf-8",
        )
        got, log = verdict(rep, specs, conds)
        joined = "\n".join(log)
        cases.append((
            "условие не создано, а пробы исполнялись — провал провязки, не третья категория",
            got == RC_RED and "зависимость" in joined and "НЕ ВЫПОЛНИЛОСЬ" not in joined,
            f"{RC_RED} + «зависимость»", got))

        # ЗАКОННЫЙ БЛИЗНЕЦ ПО ДРУГОЙ ОСИ: условие не создано, но НЕЗАВИСИМАЯ проба
        # упала по существу. Красное о продукте ПЕРЕВЕШИВАЕТ: иначе несозданное
        # условие одной части набора прятало бы дефект другой.
        rep.write_text(
            _report_of(_condition("failed", "УСЛОВИЕ ПРОГОНА НЕ СОЗДАНО"),
                       _spec("F8-01 а", "skipped", runs=0),
                       _spec("F8-02 б", "skipped", runs=0),
                       _spec("в", "failed", "expect(received).toBe(expected)")),
            encoding="utf-8",
        )
        got, log = verdict(rep, specs, conds)
        joined = "\n".join(log)
        cases.append((
            "несозданное условие не прячет красное независимой пробы",
            got == RC_RED and "сценариев без вердикта 2 из 3" in joined,
            f"{RC_RED} + «сценариев без вердикта 2 из 3»", got))

        # ИНЪЕКЦИЯ: условие объявлено в дереве, а в отчёте его нет — выпало
        # вместе со своим утверждением.
        rep.write_text(
            _report_of(_spec("а", "passed"), _spec("б", "passed"), _spec("в", "passed")),
            encoding="utf-8",
        )
        got, log = verdict(rep, specs, conds)
        joined = "\n".join(log)
        cases.append((
            "объявленное условие, выпавшее из отчёта, ловится",
            got == RC_RED and "условий объявлено 1, в отчёте 0" in joined,
            f"{RC_RED} + «условий объявлено 1, в отчёте 0»", got))

        # КРАСНЕЕТ: дерево проб пусто — «ноль упавших» из ничего.
        empty = root / "empty"
        empty.mkdir()
        rep.write_text(_report(), encoding="utf-8")
        got, _ = verdict(rep, empty)
        cases.append(("пустое дерево проб ловится", got == 1, 1, got))

    for name, ok, want, have in cases:
        print(f"  {'ОК ' if ok else 'ПРОВАЛ'} {name} (ждали {want}, получили {have})")
        if not ok:
            rc = 1
    print(f"=== самопроверка: случаев {len(cases)}, провалов {sum(1 for c in cases if not c[1])} ===")
    return rc


def main() -> int:
    if "--self-test" in sys.argv[1:]:
        return self_test()
    unknown = [a for a in sys.argv[1:] if a != "--self-test"]
    if unknown:
        # Неизвестный ввод — явный отказ. Опечатка в шаге конвейера иначе дала бы
        # зелёное, ничего не проверив.
        print(f"неизвестный аргумент: {unknown}; допустимо: без аргументов | --self-test",
              file=sys.stderr)
        return 2

    root = Path(__file__).resolve().parents[2]
    e2e = root / "ui-future" / "e2e"
    rc, log = verdict(e2e / "results.json", e2e / "specs", e2e / "preconditions")
    print("\n".join(log))
    return rc


if __name__ == "__main__":
    sys.exit(main())
